UserBalances Users::getBalance(const DbClientPtr &clientPtr) const {
    static const std::string sql = "select * from user_balances where user_id = $1";
    Result r(nullptr);
    {
        auto binder = *clientPtr << sql;
        binder << *id_ << Mode::Blocking >>
            [&r](const Result &result) { r = result; };
        binder.exec();
    }
    if (r.size() == 0)
    {
        throw UnexpectedRows("0 rows found");
    }
    else if (r.size() > 1)
    {
        throw UnexpectedRows("Found more than one row");
    }
    return UserBalances(r[0]);
}

void Users::getBalance(const DbClientPtr &clientPtr,
                       const std::function<void(UserBalances)> &rcb,
                       const ExceptionCallback &ecb) const
{
    static const std::string sql = "select * from user_balances where user_id = $1";
    *clientPtr << sql
               << *id_
               >> [rcb = std::move(rcb), ecb](const Result &r){
                    if (r.size() == 0)
                    {
                        ecb(UnexpectedRows("0 rows found"));
                    }
                    else if (r.size() > 1)
                    {
                        ecb(UnexpectedRows("Found more than one row"));
                    }
                    else
                    {
                        rcb(UserBalances(r[0]));
                    }
               }
               >> ecb;
}
